   colarete:'<circle cx="45" cy="44" r="14" fill="none" stroke="#d7a08a" stroke-width="4"/><circle cx="80" cy="50" r="10" fill="none" stroke="#d7a08a" stroke-width="4"/><circle cx="45" cy="44" r="8" fill="#e8a89a" opacity=".6"/>',
   alopecia:'<ellipse cx="60" cy="44" rx="30" ry="20" fill="#f7e1d6"/><ellipse cx="60" cy="44" rx="30" ry="20" fill="none" stroke="#e57373" stroke-width="2" stroke-dasharray="4 3"/>',
   crosta:[...Array(6)].map((_,i)=>'<path d="M'+(22+i*14)+' '+(36+(i%3)*10)+' l10 -4 l6 8 l-8 6 z" fill="#8d6e63"/>').join(""),
   nodulo:'<ellipse cx="60" cy="46" rx="20" ry="16" fill="#e99a8a" stroke="#b56b5b"/><ellipse cx="54" cy="40" rx="6" ry="4" fill="#fff" opacity=".4"/>',
   liquen:'<ellipse cx="60" cy="44" rx="40" ry="22" fill="#8d6e63" opacity=".55"/>'+[0,1,2,3].map(i=>'<path d="M24 '+(34+i*6)+' L96 '+(30+i*6)+'" stroke="#5d4037" stroke-width="1.2"/>').join(""),
   escama:[...Array(18)].map((_,i)=>'<rect x="'+(18+(i*23)%84)+'" y="'+(26+(i*13)%40)+'" width="6" height="3" rx="1" fill="#fffde7" stroke="#ccc"/>').join(""),
   erosao:'<ellipse cx="60" cy="44" rx="28" ry="16" fill="#d84343"/><ellipse cx="60" cy="44" rx="18" ry="9" fill="#f28c8c"/>',
