function vDermAtlas(){const q=norm(S.dq2||"");const L=DERMS.filter(d=>(!S.dsp||d.sp==="both"||d.sp===S.dsp)&&(!q||d._s.includes(q)));
  return '<div class="stack"><div class="row between"><h1>Atlas de dermatopatias</h1><span class="muted sm">'+L.length+'</span></div><div class="search">'+ic("search")+'<input class="inp" value="'+esc(S.dq2||"")+'" placeholder="Buscar doença ou sinal" oninput="S.dq2=this.value;clearTimeout(window._d2);window._d2=setTimeout(()=>{rerender();const i=document.querySelector(\'#app .search input\');i.focus();i.setSelectionRange(i.value.length,i.value.length)},250)" /></div>'+
  '<div class="chips"><button class="chip '+(!S.dsp?"on":"")+'" onclick="S.dsp=\'\';rerender()">Todos</button><button class="chip '+(S.dsp==="dog"?"on":"")+'" onclick="S.dsp=\'dog\';rerender()">🐕 Cão</button><button class="chip '+(S.dsp==="cat"?"on":"")+'" onclick="S.dsp=\'cat\';rerender()">🐈 Gato</button></div>'+
  '<div class="dgrid">'+L.map(d=>'<a class="item dcard" href="#/derm/d/'+d.id+'"><div class="dthumb" style="height:'+(IMGC["derm/"+d.id]?"110px;padding:0;overflow:hidden":"84px")+'">'+(IMGC["derm/"+d.id]?'<img src="'+IMGC["derm/"+d.id].f+'" alt="" loading="lazy" style="width:100%;height:100%;object-fit:cover;display:block" />':bodySVG(d.sp==="cat"?"cat":"dog",d.reg))+'</div><div class="t" style="font-size:14px">'+esc(d.n)+'</div><div class="row wrapf" style="gap:4px">'+(d.zoo?'<span class="tag t-bad">Zoonose</span>':"")+'<span class="tag t-info">'+["Sem prurido","Prurido moderado","Prurido intenso"][d.pru]+'</span></div></a>').join("")+'</div></div>'}
function vDermD(id){const d=DERMS.find(x=>x.id===id);if(!d)return'<div class="empty">Não encontrado.</div>';const far=(d.far||[]).map(n=>DRUGS.find(x=>x.n===n)).filter(Boolean);
  return '<div class="stack"><div class="card"><div class="row wrapf" style="gap:6px">'+(d.zoo?'<span class="tag t-bad">ZOONOSE</span>':"")+'<span class="tag t-info">'+["Sem prurido","Prurido moderado","Prurido intenso"][d.pru]+'</span><span class="tag t-cls">'+(d.sp==="both"?"Cães e gatos":d.sp==="dog"?"Cães":"Gatos")+'</span></div><h1 style="margin-top:8px;font-size:21px">'+esc(d.n)+'</h1>'+
  (IMGC["derm/"+d.id]?'<div style="margin-top:10px">'+imgReal("derm/"+d.id,d.n,420)+'</div>':"")+'<div class="grid g2" style="margin-top:10px"><div><div class="figbox" style="margin:0">'+bodySVG(d.sp==="cat"?"cat":"dog",d.reg)+'</div><p class="xs muted" style="text-align:center;margin:4px 0 0">Distribuição: '+d.reg.map(r=>DREG[r]).join(", ")+'</p></div><div><div class="figbox" style="margin:0">'+lesSVG(d.les)+'</div><p class="xs muted" style="text-align:center;margin:4px 0 0">Lesão: '+DLES[d.les]+'</p></div></div></div>'+
  '<div class="card kv">'+kv("Quadro clínico",d.cli)+kv("Diagnóstico",d.ex)+'</div><div class="card" style="border-color:var(--ok)"><div class="kv">'+kv("Conduta",d.cd)+'</div></div>'+
  (far.length?'<div class="card"><h3>Fármacos</h3><div class="list" style="margin-top:8px">'+far.map(drugItem).join("")+'</div></div>':"")+'<a class="btn block" href="#/derm/req">Gerar requisição de exame</a></div>'+disclaimer()}
function vDermDdx(){const a=S.ddv||(S.ddv={reg:[]});const opt=(k,l,ops)=>'<div class="field"><label>'+l+'</label><div class="row wrapf" style="gap:6px">'+ops.map(([v,t])=>'<button class="chip '+(a[k]===v?"on":"")+'" onclick="S.ddv.'+k+'=(S.ddv.'+k+'===\''+v+'\'?\'\':\''+v+'\');rerender()">'+t+'</button>').join("")+'</div></div>';
  const sc=DERMS.map(d=>{let s=0;if(a.sp&&d.sp!=="both"&&d.sp!==a.sp)return{d,s:-99};if(a.pru!=null&&a.pru!=="")s+=(+a.pru===d.pru?3:Math.abs(+a.pru-d.pru)===1?0.5:-2);if(a.les&&d.les===a.les)s+=3;if(a.zoo==="s"&&d.zoo)s+=3;
    a.reg.forEach(r=>{if(d.reg.includes(r))s+=2.5});if(a.jovem==="s"&&["demodicose-loc","demodicose-gen","dermatofitose","sarna-sarcoptica","otodectes","atopia"].includes(d.id))s+=1.5;if(a.jovem==="n"&&["hipotireoidismo","cushing","mastocitoma","cec-felino","demodicose-gen"].includes(d.id))s+=1;return{d,s}}).filter(x=>x.s>0).sort((x,y)=>y.s-x.s).slice(0,7);
  const mx=sc.length?sc[0].s:1;
  return '<div class="stack"><h1>Diferencial dermatológico</h1><p class="muted sm" style="margin:0">Primeiro passo em todo paciente com prurido: excluir ECTOPARASITAS (pulgas, sarnas) e INFECÇÕES secundárias (citologia).</p><div class="card stack">'+
  opt("sp","Espécie",[["dog","🐕 Cão"],["cat","🐈 Gato"]])+opt("pru","Prurido",[["0","Ausente"],["1","Moderado"],["2","Intenso"]])+
  '<div class="field"><label>Lesão predominante</label><div class="row wrapf" style="gap:6px">'+Object.entries(DLES).map(([k,t])=>'<button class="chip '+(a.les===k?"on":"")+'" onclick="S.ddv.les=(S.ddv.les===\''+k+'\'?\'\':\''+k+'\');rerender()">'+t+'</button>').join("")+'</div></div>'+
  '<div class="field"><label>Distribuição (marque todas)</label><div class="row wrapf" style="gap:6px">'+Object.entries(DREG).map(([k,t])=>'<button class="chip '+(a.reg.includes(k)?"on":"")+'" onclick="S.ddv.reg=S.ddv.reg.includes(\''+k+'\')?S.ddv.reg.filter(x=>x!==\''+k+'\'):S.ddv.reg.concat(\''+k+'\');rerender()">'+t+'</button>').join("")+'</div></div>'+
  opt("jovem","Paciente jovem (< 1–2 anos)?",[["s","Sim"],["n","Não (adulto/idoso)"]])+opt("zoo","Lesões em pessoas/outros animais da casa?",[["s","Sim"],["n","Não"]])+'</div>'+
  (sc.length?'<div class="card"><h3>Hipóteses</h3><div class="list" style="margin-top:8px">'+sc.map(({d,s})=>'<a class="item" href="#/derm/d/'+d.id+'"><div class="row" style="gap:10px"><div style="width:70px;flex:none">'+bodySVG(d.sp==="cat"?"cat":"dog",d.reg)+'</div><div style="flex:1;min-width:0"><div class="t" style="font-size:14px">'+esc(d.n)+'</div><div style="height:6px;background:var(--line);border-radius:4px;margin-top:6px"><div style="height:6px;border-radius:4px;background:var(--accent);width:'+Math.round(s/mx*100)+'%"></div></div>'+(d.zoo?'<span class="tag t-bad" style="margin-top:6px">Zoonose</span>':"")+'</div></div></a>').join("")+'</div></div>':'<div class="empty">Marque as características acima.</div>')+
  '<button class="btn" onclick="S.ddv={reg:[]};rerender()">Limpar</button></div>'}
function vDermEx(){const E=[["Raspado cutâneo profundo","Demodex (espremer a pele, raspar até sangrar levemente).","Óleo mineral + lâmina; várias áreas."],["Raspado superficial","Sarcoptes, Notoedres, Cheyletiella.","Áreas não escoriadas (bordas de orelha, cotovelos); sensibilidade baixa para Sarcoptes."],["Tricograma","Pontas quebradas (lambedura), Demodex, esporos de dermatófitos, fase do ciclo do pelo.","Arrancar pelos no sentido do crescimento."],["Fita de acetato","Malassezia, bactérias, Cheyletiella.","Pressionar a fita na pele e corar (Panótico)."],["Citologia por imprint/swab","Pioderma (cocos + neutrófilos), Malassezia, acantócitos (pênfigo), leveduras (esporotricose).","Pústula intacta = melhor amostra."],["Lâmpada de Wood","Microsporum canis (fluorescência verde-maçã na haste).","Aquecer 5 min; falso-negativo em ~50%."],["Cultura fúngica (DTM)","Dermatófitos (padrão-ouro) — também para monitorar a cura.","Técnica do escovado (Mackenzie)."],["Citologia aspirativa","Nódulos (mastocitoma, histiocitoma, lipoma).","Sempre antes da cirurgia de nódulos."],["Biópsia","Doenças autoimunes, neoplasias, lesões atípicas, refratárias.","Punch 6–8 mm, NÃO preparar/limpar a pele; lesões primárias; formol 10%."],["Cultura bacteriana e antibiograma","Pioderma recorrente, profunda ou sem resposta (MRSP).","Pústula intacta ou tecido."],["Dieta de eliminação","Alergia alimentar.","8 semanas, proteína hidrolisada/nova, sem petiscos; depois desafio."]];
  return '<div class="stack"><h1>Exames dermatológicos</h1>'+E.map(([n,o,t])=>'<div class="card"><h3>'+n+'</h3><div class="kv" style="margin-top:6px">'+kv("Detecta",o)+kv("Técnica",t)+'</div></div>').join("")+'</div>'+disclaimer()}
function vDermReq(){const B=S.dreq||(S.dreq=store.get("dreq",{}));const inp=(k,l,ph)=>'<div class="field"><label>'+l+'</label><input class="inp" value="'+esc(B[k]||"")+'" placeholder="'+(ph||"")+'" oninput="S.dreq.'+k+'=this.value;store.set(\'dreq\',S.dreq)" /></div>';
  return '<div class="stack"><h1>Requisição de exame</h1><div class="card"><div class="grid g2m">'+inp("pac","Paciente (nome)")+inp("sp","Espécie/raça")+inp("idade","Idade/sexo")+inp("tut","Tutor")+inp("ex","Exame","citologia / biópsia / cultura fúngica / cultura bacteriana")+inp("loc","Local da coleta")+inp("tempo","Tempo de evolução")+inp("trat","Tratamentos prévios")+'</div>'+
  '<div class="field" style="margin-top:10px"><label>Descrição clínica</label><textarea class="inp" oninput="S.dreq.cli=this.value;store.set(\'dreq\',S.dreq)">'+esc(B.cli||"")+'</textarea></div><div class="field" style="margin-top:10px"><label>Hipóteses diagnósticas</label><input class="inp" value="'+esc(B.hip||"")+'" oninput="S.dreq.hip=this.value;store.set(\'dreq\',S.dreq)" /></div>'+
  '<div class="actions" style="margin-top:12px"><button class="btn pri" onclick="reqPrint()">'+ic("print",18)+' Imprimir / PDF</button><button class="btn" onclick="copy(reqText())">'+ic("copy",18)+' Copiar</button></div></div></div>'}
function reqText(){const B=S.dreq||{},D=S.doc;return ["REQUISIÇÃO DE EXAME — "+(B.ex||"").toUpperCase(),"Solicitante: "+(D.nome||"")+(D.crmv?" — CRMV "+D.crmv:""),"Paciente: "+(B.pac||"")+" | Espécie/raça: "+(B.sp||"")+" | Idade/sexo: "+(B.idade||"")+" | Tutor: "+(B.tut||""),"Local da coleta: "+(B.loc||"")+" | Evolução: "+(B.tempo||""),"Tratamentos prévios: "+(B.trat||""),"Descrição clínica: "+(B.cli||""),"Hipóteses: "+(B.hip||""),"Data: "+new Date().toLocaleDateString("pt-BR")].join("\n")}
function reqPrint(){document.getElementById("printArea").innerHTML='<div class="rx-page"><div class="rx-h"><b>'+esc(S.doc.clinica||"Requisição de Exame")+'</b></div><pre style="white-space:pre-wrap;font-family:Georgia,serif;font-size:14px;line-height:1.7">'+esc(reqText())+'</pre><div class="rx-foot">_______________________________________<br/>'+esc(S.doc.nome||"Assinatura e carimbo")+(S.doc.crmv?" — CRMV "+esc(S.doc.crmv):"")+'</div></div>';
  if(window.AndroidPrint&&AndroidPrint.print){setTimeout(()=>{try{AndroidPrint.print("Requisicao")}catch(e){}},250);return}try{window.print()}catch(e){}}
function vDerm(arg,id){if(arg==="atlas")return vDermAtlas();if(arg==="d")return vDermD(id);if(arg==="ddx")return vDermDdx();if(arg==="exames")return vDermEx();if(arg==="req")return vDermReq();return vDermHub()}

/* ================= Odontograma veterinário (Triadan modificado — várias espécies) ================= */
const TRI={dog:{q1:[110,109,108,107,106,105,104,103,102,101],q2:[201,202,203,204,205,206,207,208,209,210],q4:[411,410,409,408,407,406,405,404,403,402,401],q3:[301,302,303,304,305,306,307,308,309,310,311]},
 cat:{q1:[109,108,107,106,104,103,102,101],q2:[201,202,203,204,206,207,208,209],q4:[409,408,407,404,403,402,401],q3:[301,302,303,304,307,308,309]},
 horse:{q1:[111,110,109,108,107,106,105,104,103,102,101],q2:[201,202,203,204,205,206,207,208,209,210,211],q4:[411,410,409,408,407,406,405,404,403,402,401],q3:[301,302,303,304,305,306,307,308,309,310,311]},
 rabbit:{q1:[111,110,109,108,107,106,102,101],q2:[201,202,206,207,208,209,210,211],q4:[411,410,409,408,407,401],q3:[301,307,308,309,310,311]},
 gp:{q1:[111,110,109,108,101],q2:[201,208,209,210,211],q4:[411,410,409,408,401],q3:[301,308,309,310,311]},
 rat:{q1:[111,110,109,101],q2:[201,209,210,211],q4:[411,410,409,401],q3:[301,309,310,311]},
 ferret:{q1:[109,108,107,106,104,103,102,101],q2:[201,202,203,204,206,207,208,209],q4:[410,409,408,407,406,404,403,402,401],q3:[301,302,303,304,306,307,308,309,310]}};
const ODSP=[["dog","🐕 Cão","cão (42 dentes)"],["cat","🐈 Gato","gato (30 dentes)"],["horse","🐎 Equino","equino (36–44 dentes)"],["rabbit","🐇 Coelho","coelho (28 dentes)"],["gp","🐹 Porquinho-da-índia/chinchila","porquinho-da-índia/chinchila (20 dentes)"],["rat","🐀 Rato/hamster","rato/hamster (16 dentes)"],["ferret","🦦 Furão","furão (34 dentes)"],["idade","📅 Idade pelos dentes",""]];
const ODGRP=sp=>sp==="horse"?"eq":["rabbit","gp","rat"].includes(sp)?"ex":"pc";
const FIND={eq:["Ponta de esmalte (lesão de bochecha/língua)","Gancho","Rampa","Onda","Degrau","Diastema (impactação alimentar)","Cárie infundibular","Fratura","Mobilidade","EOTRH (reabsorção/hipercementose de incisivos)","Doença periodontal","Dente decíduo retido (capa)","Sobrecrescimento (dente oposto ausente)"],
 ex:["Sobrecrescimento/alongamento de coroa","Maloclusão","Espícula/ponta (lesão de língua ou bochecha)","Alongamento de raiz (apical)","Abscesso periapical","Mobilidade","Fratura","Alteração de esmalte/descoloração"]};
function triInfo(sp,n){const q=Math.floor(n/100),t=n%100,up=q<=2;const side=(q===1||q===4?" direito":" esquerdo");
  let nm=t<=3?"Incisivo "+["","1º","2º","3º"][t]:t===4?"Canino":t<=8?(t-4)+"º pré-molar":(t-8)+"º molar";
  if(sp==="horse"&&t<=3)nm="Incisivo "+["","central (pinça)","intermediário (médio)","lateral (canto)"][t];
  if(sp==="horse"&&t===5)nm="1º pré-molar (dente de lobo)";
  if(sp==="cat"&&t===9)nm="1º molar";
  if(sp==="rabbit"&&n%100===2&&up)nm="Incisivo 2º (dente cavilha — “peg tooth”)";
  let r="",note="";
  if(sp==="dog"||sp==="cat"){let k=1;if(sp==="dog"){if(up)k=t<=5?1:t<=7?2:3;else k=t<=5?1:t<=10?2:1}else{if(up)k=t<=6?1:t===7?2:t===8?3:2;else k=t<=4?1:2}r=k+(k>1?" raízes":" raiz")}
  else if(sp==="horse")r=t>=6?"Hipsodonte (coroa de reserva, erupção contínua até ~20–25 anos)":t===5?"Braquidonte, raiz curta":"Hipsodonte";
  else if(sp==="rabbit"||sp==="gp")r="Elodonte — raízes abertas, crescimento contínuo";
  else if(sp==="rat")r=t<=3?"Elodonte — crescimento contínuo":"Raízes fechadas (sem crescimento contínuo)";
  else if(sp==="ferret")r="Braquidonte (crescimento limitado)";
  const notes={dog:{108:"Dente carniceiro superior — abscesso pode fistular abaixo do olho (fístula infraorbitária).",208:"Dente carniceiro superior — fístula infraorbitária.",309:"Dente carniceiro inferior.",409:"Dente carniceiro inferior.",104:"Raiz longa; doença periodontal pode causar fístula oronasal.",204:"Raiz longa; fístula oronasal."},
   cat:{307:"Local frequente de reabsorção dentária.",308:"Local frequente de reabsorção dentária.",309:"Carniceiro inferior — reabsorção frequente.",409:"Carniceiro inferior — reabsorção frequente.",407:"Reabsorção frequente.",408:"Reabsorção frequente.",108:"Carniceiro superior.",208:"Carniceiro superior."},
   horse:{105:"Dente de lobo: presente em parte dos cavalos; pode interferir com a embocadura — extração comum.",205:"Dente de lobo — extração comum.",305:"Dente de lobo inferior (raro).",405:"Dente de lobo inferior (raro).",104:"Canino: presente sobretudo em machos (erupção 4–5 anos).",204:"Canino: sobretudo em machos.",304:"Canino: sobretudo em machos.",404:"Canino: sobretudo em machos.",106:"Ganchos rostrais frequentes (sobretudo se 306/406 menores).",206:"Ganchos rostrais frequentes.",311:"Ganchos caudais frequentes.",411:"Ganchos caudais frequentes.",108:"Raízes de 108–111 relacionadas ao seio maxilar (sinusite de origem dentária).",208:"Raízes de 208–211 relacionadas ao seio maxilar.",109:"Raízes relacionadas ao seio maxilar — infecção apical causa sinusite.",209:"Raízes relacionadas ao seio maxilar.",101:"Avaliar cálice/infundíbulo e mesa para estimar a idade (aba Idade).",301:"Avaliar mesa e rasamento para estimativa de idade."},
   rabbit:{101:"Incisivos crescem ~2 mm/semana: maloclusão leva a sobrecrescimento rápido.",102:"Dente cavilha: diferencial de lagomorfos (2 pares de incisivos superiores).",301:"Incisivo inferior: corte com broca, NUNCA com alicate (fissuras e abscessos).",106:"Pré-molares/molares: pontas laterais (vestibulares) nos superiores e linguais nos inferiores."},
   gp:{101:"Hipovitaminose C predispõe a doença dentária e periodontal (suplementar ~10–30 mg/kg/dia).",308:"Pré-molares inferiores tendem a formar pontes sobre a língua (aprisionamento lingual)."},
   rat:{101:"Incisivos amarelo-alaranjados são NORMAIS (ferro no esmalte); brancos podem indicar deficiência/doença.",301:"Sobrecrescimento de incisivos é a afecção dentária mais comum."},
   ferret:{104:"Fratura de ponta de canino é comum; avaliar exposição pulpar.",109:"Doença periodontal e cálculo frequentes em furões adultos."}};
  note=(notes[sp]||{})[n]||"";
  return{nm:nm+(up?" superior":" inferior")+side,r,note}}
function odTog(sp,n,i){const x=S.ov[sp][n]||(S.ov[sp][n]={});const f=x.f||(x.f=[]);const k=f.indexOf(i);if(k>=0)f.splice(k,1);else f.push(i);store.set("ovet",S.ov);rerender()}
function vOdV(){const sp=S.ovsp||"dog";if(sp==="idade")return vOdIdade();const O=S.ov||(S.ov=store.get("ovet",{dog:{},cat:{}}));const D=O[sp]||(O[sp]={});const T=TRI[sp];const G=ODGRP(sp);
  const all=[...T.q1,...T.q2,...T.q3,...T.q4];const sel=all.includes(+S.ovt)?+S.ovt:({dog:108,cat:307,horse:106,rabbit:101,gp:101,rat:101,ferret:104})[sp];
  const st=n=>{const x=D[n]||{};return x.aus?"aus":x.ext?"bad":(x.pd>=3||x.tr>=1||x.fx||(x.f&&x.f.length))?"bad":x.pd>=1?"ok":""};
  const btn=n=>'<button class="tb '+st(n)+(n===sel?" on":"")+'" style="min-width:30px" onclick="S.ovt='+n+';rerender()">'+n+'</button>';
  const row=(a,b)=>'<div style="display:flex;justify-content:center;gap:2px"><div style="display:flex;gap:2px;padding-right:5px;border-right:2px solid var(--line-2)">'+a.map(btn).join("")+'</div><div style="display:flex;gap:2px;padding-left:5px">'+b.map(btn).join("")+'</div></div>';
  const x=D[sel]||(D[sel]={});const info=triInfo(sp,sel);const save=()=>"store.set('ovet',S.ov)";
  const sel2=(k,l,ops)=>'<div class="field"><label>'+l+'</label><select class="inp" onchange="S.ov.'+sp+'['+sel+'].'+k+'=num(this.value);'+save()+';rerender()">'+ops.map(([v,t])=>'<option value="'+v+'" '+((x[k]||0)==v?"selected":"")+'>'+t+'</option>').join("")+'</select></div>';
  const cnt=f=>all.filter(n=>D[n]&&f(D[n])).length;const w=Math.max(T.q1.length+T.q2.length,T.q3.length+T.q4.length)*32+30;
  const fields=G==="pc"?'<div class="grid g2m" style="margin-top:10px">'+sel2("pd","Doença periodontal (AVDC)",[[0,"PD0 — normal"],[1,"PD1 — gengivite"],[2,"PD2 — < 25% perda de inserção"],[3,"PD3 — 25–50%"],[4,"PD4 — > 50%"]])+sel2("mob","Mobilidade",[[0,"M0"],[1,"M1 (até 1 mm)"],[2,"M2 (> 1 mm)"],[3,"M3 (vertical)"]])+sel2("fr","Furca",[[0,"F0"],[1,"F1"],[2,"F2"],[3,"F3 (exposta)"]])+(sp==="cat"?sel2("tr","Reabsorção dentária (TR)",[[0,"Ausente"],[1,"TR1 — cemento/esmalte"],[2,"TR2 — dentina"],[3,"TR3 — até a polpa"],[4,"TR4 — coroa extensa"],[5,"TR5 — só raízes"]]):"")+sel2("fx","Fratura",[[0,"Ausente"],[1,"Esmalte"],[2,"Coroa não complicada"],[3,"Complicada (exposição pulpar)"],[4,"Raiz"]])+'</div>'
   :'<div class="xs muted" style="font-weight:800;margin-top:10px">ACHADOS (toque para marcar)</div><div class="row wrapf" style="gap:6px;margin-top:6px">'+FIND[G].map((t,i)=>'<button class="chip '+((x.f||[]).includes(i)?"on":"")+'" onclick="odTog(\''+sp+'\','+sel+','+i+')">'+t+'</button>').join("")+'</div>';
  const fi=(x.f||[]);const alerts=(x.fx===3?'<div class="note warn" style="margin-top:8px">Fratura com exposição pulpar: tratamento endodôntico ou extração — nunca apenas observar (necrose e abscesso).</div>':"")+((x.pd===4||x.mob===3)?'<div class="note warn" style="margin-top:8px">PD4/M3: extração geralmente indicada.</div>':"")+((x.tr>=2)?'<div class="note warn" style="margin-top:8px">Reabsorção TR2+: extração (ou amputação de coroa em reabsorção tipo 2 sem periodontite/estomatite — avaliar radiografia).</div>':"")+
   (G==="eq"&&fi.length?'<div class="note info" style="margin-top:8px">Correção (odontoplastia) com grosas/equipamento motorizado sob sedação (detomidina ± butorfanol) e abre-boca; evitar remover coroa em excesso (risco de exposição pulpar/térmica). Sinusite, fístula ou fratura: radiografia/TC.</div>':"")+
   (G==="ex"&&fi.length?'<div class="note warn" style="margin-top:8px">Investigar a CAUSA: dieta pobre em fibra (feno à vontade é o tratamento base), hipovitaminose C (porquinho-da-índia), distúrbios de cálcio/vit. D, trauma, genética (braquicefálicos). Desgaste com broca sob anestesia a cada 4–8 semanas se necessário; abscessos: debridamento cirúrgico + antimicrobiano seguro para a espécie; radiografia/TC do crânio.</div>':"");
  const sum=G==="pc"?'<div class="res"><b>'+cnt(t=>t.pd>=3)+'</b><span>dentes PD3–PD4</span></div><div class="res"><b>'+cnt(t=>t.ext)+'</b><span>extrações indicadas</span></div><div class="res"><b>'+cnt(t=>t.aus)+'</b><span>ausentes</span></div><div class="res"><b>'+cnt(t=>sp==="cat"?t.tr>=1:t.fx>=1)+'</b><span>'+(sp==="cat"?"com reabsorção":"com fratura")+'</span></div>'
   :'<div class="res"><b>'+cnt(t=>t.f&&t.f.length)+'</b><span>dentes com achados</span></div><div class="res"><b>'+cnt(t=>t.ext)+'</b><span>extrações indicadas</span></div><div class="res"><b>'+cnt(t=>t.aus)+'</b><span>ausentes</span></div>';
  return '<div class="stack"><h1>Odontograma</h1><div class="chips">'+ODSP.map(([k,l])=>'<button class="chip '+(sp===k?"on":"")+'" onclick="S.ovsp=\''+k+'\';S.ovt=null;rerender()">'+l+'</button>').join("")+'</div>'+
  '<div class="card scroll-x" style="padding:10px 4px"><div style="min-width:'+w+'px" class="stack">'+row(T.q1,T.q2)+'<div style="height:2px;background:var(--line-2);margin:4px 8px"></div>'+row(T.q4,T.q3)+'</div></div><p class="xs muted" style="text-align:center;margin:0">Sistema Triadan modificado (1º dígito: quadrante 1 sup. dir., 2 sup. esq., 3 inf. esq., 4 inf. dir.) · Laranja: alteração/extração · Verde: gengivite/PD1–2</p>'+
  '<div class="card"><div class="xs muted" style="font-weight:800">DENTE '+sel+'</div><h2 style="margin-top:4px">'+esc(info.nm)+'</h2><div class="sm muted">'+esc(info.r)+'</div>'+(info.note?'<div class="note info" style="margin-top:8px">'+esc(info.note)+'</div>':"")+fields+
  '<div class="row wrapf" style="gap:6px;margin-top:10px"><button class="chip '+(x.aus?"on":"")+'" onclick="S.ov.'+sp+'['+sel+'].aus=S.ov.'+sp+'['+sel+'].aus?0:1;'+save()+';rerender()">Ausente</button><button class="chip '+(x.ext?"on":"")+'" onclick="S.ov.'+sp+'['+sel+'].ext=S.ov.'+sp+'['+sel+'].ext?0:1;'+save()+';rerender()">Extração indicada</button></div>'+alerts+'</div>'+
  '<div class="out"><div class="lbl">Resumo — '+(ODSP.find(s=>s[0]===sp)||[])[2]+'</div><div class="res-grid" style="margin-top:8px">'+sum+'</div>'+
  '<div class="actions" style="margin-top:10px"><button class="btn sm" onclick="copy(ovText())">'+ic("copy",16)+' Copiar resumo</button><button class="btn sm" onclick="if(confirm(\'Limpar este odontograma?\')){S.ov.'+sp+'={};'+save()+';rerender()}">Limpar</button></div><div class="xs muted" style="margin-top:8px">'+(G==="pc"?"Avaliação periodontal completa exige anestesia geral, sondagem e radiografias intraorais (AAHA/AVDC).":G==="eq"?"Exame odontológico anual (semestral em jovens de 2–5 anos e em idosos), com sedação, abre-boca, lanterna e espelho.":"Exame completo exige anestesia/sedação e otoscópio ou endoscópio — a cavidade oral é estreita; radiografia de crânio para raízes.")+'</div></div></div>'+disclaimer()}
function ovText(){const sp=S.ovsp||"dog",D=(S.ov||{})[sp]||{},G=ODGRP(sp);const L=["Odontograma — "+((ODSP.find(s=>s[0]===sp)||[])[2]||sp)+" — "+new Date().toLocaleDateString("pt-BR")];
  Object.keys(D).sort().forEach(n=>{const x=D[n];const f=[x.aus?"ausente":"",x.pd?"PD"+x.pd:"",x.mob?"M"+x.mob:"",x.fr?"F"+x.fr:"",x.tr?"TR"+x.tr:"",x.fx?"fratura "+["","esmalte","coroa não complicada","complicada","raiz"][x.fx]:""].concat((x.f||[]).map(i=>(FIND[G]||[])[i]||"")).concat([x.ext?"EXTRAÇÃO INDICADA":""]).filter(Boolean);if(f.length)L.push(n+": "+f.join(", "))});return L.join("\n")}
function vOdIdade(){const t=(h,rows)=>'<div class="card scroll-x"><h3>'+h+'</h3><table class="tbl" style="margin-top:8px"><tbody>'+rows.map(r=>'<tr><td><b>'+r[0]+'</b></td><td>'+r[1]+'</td></tr>').join("")+'</tbody></table></div>';
 return '<div class="stack"><h1>Odontograma</h1><div class="chips">'+ODSP.map(([k,l])=>'<button class="chip '+((S.ovsp||"dog")===k?"on":"")+'" onclick="S.ovsp=\''+k+'\';S.ovt=null;rerender()">'+l+'</button>').join("")+'</div><p class="muted sm" style="margin:0">Estimativa de idade pela dentição — valores aproximados; variam com raça, dieta e manejo (zebuínos e animais a pasto tendem a ser mais tardios).</p>'+
 t("Equino — incisivos",[["Decíduos","Pinças: 1ª semana · médios: 4–6 semanas · cantos: 6–9 meses"],["Troca por permanentes","Pinças: 2,5 anos · médios: 3,5 anos · cantos: 4,5 anos (boca feita aos 5) · caninos (machos): 4–5 anos"],["Rasamento inferior (desaparece o 'copo'/infundíbulo)","Pinças: 6 anos · médios: 7 anos · cantos: 8 anos"],["Rasamento superior","Pinças: 9 anos · médios: 10 anos · cantos: 11 anos"],["Estrela dentária","Surge nas pinças ~8 anos e fica central/redonda com a idade"],["Gancho no canto superior","~7 anos (pode reaparecer ~11–13)"],["Sulco de Galvayne (canto superior)","Aparece ~10 anos · metade do dente ~15 · todo o dente ~20 · desaparece ~30"],["Forma da mesa","Oval (até ~9) → redonda (~9–13) → triangular (~14–17) → biangular (> 17 anos)"]])+
 t("Bovino — incisivos (sem incisivos superiores: pulvino dental)",[["Pinças (1º par) permanentes","18–24 meses — '2 dentes'"],["1º médios (2º par)","24–30 meses — '4 dentes'"],["2º médios (3º par)","30–36 meses — '6 dentes'"],["Cantos (4º par)","36–48 meses — '8 dentes'/boca cheia"],["Uso prático","Classificação de maturidade de carcaça (0, 2, 4, 6, 8 dentes); compra e venda; manejo reprodutivo"]])+
 t("Ovino e caprino — incisivos",[["Pinças","~12–18 meses"],["1º médios","~18–24 meses"],["2º médios","~30–36 meses"],["Cantos","~36–48 meses (boca cheia)"],["Idosos","Dentes desgastados/perdidos ('boca quebrada') — descarte"]])+
 t("Cão e gato — erupção",[["Cão — decíduos","3–6 semanas (28 dentes)"],["Cão — permanentes","Incisivos 3–5 meses · caninos 4–6 meses · pré-molares 4–6 meses · molares 5–7 meses (42 dentes)"],["Gato — decíduos","2–6 semanas (26 dentes)"],["Gato — permanentes","3–6 meses (30 dentes)"],["Decíduo persistente","Canino decíduo presente com o permanente erupcionado = extrair (maloclusão, doença periodontal)"]])+
 t("Coelho e roedores",[["Coelho","Nasce com dentes decíduos que caem até ~5 semanas (alguns in utero); não há estimativa de idade confiável pelos dentes"],["Rato","Incisivos amarelo-alaranjados no adulto (normal); crescimento contínuo"]])+'</div>'+disclaimer()}

/* ================= Escalas clínicas ================= */
const GCMPS=[["Vocalização (observar no canil)",["Quieto","Chorando/choramingando","Gemendo","Gritando"]],["Atenção à ferida",["Ignora","Olha para a ferida","Lambe","Esfrega","Morde"]],["Mobilidade (pular se não puder andar)",["Normal","Manca","Lento ou relutante","Rígido","Recusa-se a mover"]],["Resposta ao toque (pressionar ~5 cm ao redor da ferida)",["Nada","Olha em volta","Retrai-se","Rosna ou protege","Tenta morder","Chora"]],["Comportamento geral",["Feliz/contente ou alegre","Quieto","Indiferente ou não responsivo","Nervoso, ansioso ou com medo","Deprimido ou não responsivo"]],["Postura/conforto",["Confortável","Inquieto","Agitado","Encurvado ou tenso","Rígido"]]];
const FGS=[["Posição das orelhas",["Normais, para frente","Levemente afastadas","Achatadas e rodadas para fora"]],["Aperto orbital (olhos)",["Abertos","Parcialmente fechados","Semicerrados/fechados"]],["Tensão do focinho",["Relaxado (redondo)","Levemente tenso","Tenso (elíptico)"]],["Posição dos bigodes",["Soltos, curvos","Levemente curvos/retos","Retos, para frente"]],["Posição da cabeça",["Acima da linha dos ombros","Alinhada com os ombros","Abaixo dos ombros/inclinada"]]];
const MGCS=[["Atividade motora",["Postura normal, reflexos espinhais normais","Hemiparesia, tetraparesia ou atividade de descerebração","Decúbito, rigidez extensora intermitente","Decúbito, rigidez extensora constante","Decúbito, rigidez extensora constante com opistótono","Decúbito, hipotonia muscular, reflexos espinhais deprimidos/ausentes"].reverse()],["Reflexos do tronco encefálico",["Pupilas normais e reflexo pupilar normal, reflexo oculocefálico normal","Reflexo pupilar lento, oculocefálico normal a reduzido","Miose bilateral não responsiva, oculocefálico normal a reduzido","Pupilas puntiformes, oculocefálico reduzido a ausente","Midríase unilateral não responsiva, oculocefálico reduzido a ausente","Midríase bilateral não responsiva, oculocefálico reduzido a ausente"].reverse()],["Nível de consciência",["Períodos ocasionais de alerta e responsivo ao ambiente","Depressão ou delírio, responde inadequadamente","Semicomatoso, responsivo a estímulos visuais","Semicomatoso, responsivo a estímulos auditivos","Semicomatoso, responsivo apenas a estímulo nocivo repetido","Comatoso, não responsivo a estímulo nocivo repetido"].reverse()]];
const ECC=[[1,"Costelas, vértebras e ossos pélvicos facilmente visíveis à distância; sem gordura; perda muscular evidente."],[2,"Costelas, vértebras e pelve facilmente visíveis; sem gordura palpável; mínima perda muscular."],[3,"Costelas facilmente palpáveis e podem ser visíveis; topo das vértebras visível; cintura e retração abdominal evidentes."],[4,"Costelas facilmente palpáveis com mínima cobertura de gordura; cintura facilmente vista de cima; retração abdominal evidente."],[5,"IDEAL: costelas palpáveis sem excesso de gordura; cintura visível atrás das costelas; abdome retraído de perfil."],[6,"Costelas palpáveis com leve excesso de gordura; cintura discernível de cima, mas não proeminente."],[7,"Costelas palpáveis com dificuldade; depósitos de gordura na região lombar e base da cauda; cintura ausente ou pouco visível."],[8,"Costelas não palpáveis sob gordura espessa; depósitos acentuados na lombar e cauda; sem cintura; possível distensão abdominal."],[9,"Grandes depósitos de gordura no tórax, coluna e base da cauda; depósitos no pescoço e membros; distensão abdominal evidente."]];
function scoreBlock(key,items,start){const v=S[key]||(S[key]={});return items.map(([t,ops],i)=>'<div class="card"><h3 style="font-size:15px">'+(i+1)+'. '+t+'</h3><div class="list" style="margin-top:8px">'+ops.map((o,j)=>{const sc=start+j;return '<button class="item" style="text-align:left;padding:9px 12px;'+(v[i]===sc?"border-color:var(--accent);background:var(--accent-soft)":"")+'" onclick="S.'+key+'['+i+']='+sc+';rerender()"><div class="row between"><span class="sm">'+esc(o)+'</span><b>'+sc+'</b></div></button>'}).join("")+'</div></div>').join("")}
function vEsc(arg){const tabs=[["dor-cao","Dor — cão"],["dor-gato","Dor — gato"],["ecc","Condição corporal"],["coma","Coma (MGCS)"]];arg=arg||"dor-cao";let body="",out="";
 if(arg==="dor-cao"){body='<p class="muted sm" style="margin:0">Escala Composta de Dor de Glasgow — forma reduzida (CMPS-SF). Avaliar em sequência, sem interferência.</p>'+scoreBlock("gc",GCMPS,0);const v=S.gc||{};const n=Object.keys(v).length;const tot=Object.values(v).reduce((a,b)=>a+b,0);const semMob=v[2]==null;const lim=semMob?5:6;
  if(n>=5)out='<div class="lbl">Escore</div><div class="big">'+tot+(semMob?" / 20":" / 24")+'</div><div class="note '+(tot>=lim?"bad":"ok")+'" style="margin-top:8px">'+(tot>=lim?"Escore ≥ "+lim+(semMob?"/20":"/24")+": ANALGESIA DE RESGATE indicada; reavaliar em 30–60 min.":"Abaixo do limiar de intervenção ("+lim+(semMob?"/20":"/24")+"); manter protocolo e reavaliar periodicamente.")+'</div>'}
 if(arg==="dor-gato"){body='<p class="muted sm" style="margin:0">Feline Grimace Scale — observar o gato sem interação por ~30 s (não aplicar dormindo).</p>'+scoreBlock("fg",FGS,0);const v=S.fg||{};const n=Object.keys(v).length;const tot=Object.values(v).reduce((a,b)=>a+b,0);
  if(n>=5)out='<div class="lbl">Escore</div><div class="big">'+tot+' / 10</div><div class="note '+(tot>=4?"bad":"ok")+'" style="margin-top:8px">'+(tot>=4?"≥ 4/10: ANALGESIA DE RESGATE indicada; reavaliar 1 h após.":"< 4/10: dor ausente/controlada; reavaliar periodicamente.")+'</div>'}
 if(arg==="ecc"){const e=S.ecc||5;body='<p class="muted sm" style="margin:0">Escore de condição corporal (1–9, WSAVA). Cada ponto acima de 5 ≈ 10% acima do peso ideal.</p><div class="card"><div class="list">'+ECC.map(([n,t])=>'<button class="item" style="text-align:left;'+(e===n?"border-color:var(--accent);background:var(--accent-soft)":"")+'" onclick="S.ecc='+n+';rerender()"><div class="row" style="align-items:flex-start;gap:10px"><b style="font-size:20px;min-width:24px">'+n+'</b><span class="sm">'+t+'</span></div></button>').join("")+'</div></div><div class="card grid g2m">'+'<div class="field"><label>Peso atual (kg)</label><input class="inp" type="number" step="any" value="'+esc(S.eccw||"")+'" onchange="S.eccw=this.value;rerender()" /></div><div class="field"><label>Massa muscular</label><select class="inp" onchange="S.ecm=this.value;rerender()">'+["Normal","Perda leve","Perda moderada","Perda grave"].map(o=>'<option '+(S.ecm===o?"selected":"")+'>'+o+'</option>').join("")+'</select></div></div>';
  const w=num(S.eccw);if(w){const ideal=w*100/(100+(e-5)*10);out='<div class="lbl">Peso ideal estimado</div><div class="big">'+fmt(ideal,1)+' kg</div><div class="sm">'+(e>5?"Excesso de ~"+((e-5)*10)+"% — plano de perda de 1–2%/semana (cães) ou 0,5–2% (gatos).":e<4?"Abaixo do ideal: investigar causa e aumentar aporte calórico.":"Condição corporal adequada.")+(S.ecm&&S.ecm!=="Normal"?" Atenção à perda muscular (sarcopenia/caquexia) — garantir proteína adequada.":"")+'</div><a class="btn sm" style="margin-top:10px" href="#/calc/energia" onclick="S.calcW[S.calcSp]='+(+ideal.toFixed(1))+';store.set(\'calcW\',S.calcW)">Calcular energia com o peso ideal</a>'}}
 if(arg==="coma"){body='<p class="muted sm" style="margin:0">Escala de Coma de Glasgow Modificada (Platt) — trauma cranioencefálico. Reavaliar a cada 30–60 min.</p>'+scoreBlock("gcs",MGCS,1);const v=S.gcs||{};if(Object.keys(v).length>=3){const tot=v[0]+v[1]+v[2];out='<div class="lbl">Escore</div><div class="big">'+tot+' / 18</div><div class="note '+(tot<=8?"bad":tot<=14?"warn":"ok")+'" style="margin-top:8px">'+(tot<=8?"3–8: prognóstico GRAVE.":tot<=14?"9–14: prognóstico RESERVADO.":"15–18: prognóstico BOM.")+' Escore ≤ 8 associado a ~50% de mortalidade em 48 h (Platt, 2001). Manter perfusão e oxigenação, cabeça elevada 15–30°, considerar manitol/salina hipertônica.</div>'}}
 return '<div class="stack"><h1>Escalas clínicas</h1><div class="chips">'+tabs.map(([k,l])=>'<a class="chip '+(arg===k?"on":"")+'" href="#/escalas/'+k+'" style="text-decoration:none">'+l+'</a>').join("")+'</div>'+body+(out?'<div class="out">'+out+'</div>':"")+
 (arg!=="ecc"?'<button class="btn" onclick="S.'+({"dor-cao":"gc","dor-gato":"fg",coma:"gcs"})[arg]+'={};rerender()">Zerar</button>':"")+'</div>'+disclaimer()}

/* ================= Calculadoras extras ================= */
const ANV=[{n:"Lidocaína 2% (20 mg/mL)",c:20,dog:6,cat:3},{n:"Lidocaína 2% com epinefrina",c:20,dog:8,cat:4},{n:"Bupivacaína 0,5% (5 mg/mL)",c:5,dog:2,cat:1},{n:"Ropivacaína 0,75% (7,5 mg/mL)",c:7.5,dog:3,cat:1.5},{n:"Ropivacaína 0,5% (5 mg/mL)",c:5,dog:3,cat:1.5},{n:"Mepivacaína 2% (20 mg/mL)",c:20,dog:5,cat:2.5}];
function calcAnestV(){const a=ANV[num(document.getElementById("avA").value)],sp=document.getElementById("avS").value,w=gv("avW"),u=gv("avU");const o=document.getElementById("avO");if(!o)return;
  const max=a[sp]*w,ml=max/a.c,rest=ml-u;o.innerHTML='<div class="lbl">Volume máximo total</div><div class="big">'+fmt(ml)+' mL</div><div class="sm muted">'+fmt(max)+' mg ('+fmt(a[sp])+' mg/kg)</div><div class="res-grid" style="margin-top:10px"><div class="res"><b style="color:'+(rest<0?"var(--bad)":"inherit")+'">'+fmt(Math.max(rest,0))+' mL</b><span>restante ('+fmt(u)+' mL usados)</span></div><div class="res"><b>'+fmt(ml/4,2)+' mL</b><span>por ponto em bloqueio de 4 pontos (ex.: dentários)</span></div></div>'+
  (rest<0?'<div class="note bad" style="margin-top:10px"><b>Dose máxima ultrapassada</b> — monitorar sinais de toxicidade (tremores, convulsão, bradicardia, hipotensão). Antídoto: emulsão lipídica 20%.</div>':"")+(sp==="cat"?'<div class="note warn" style="margin-top:10px">Gatos são mais sensíveis aos anestésicos locais: em filhotes e gatos pequenos o volume seguro é muito pequeno — dilua com salina para ganhar volume, sem ultrapassar a dose em mg.</div>':"")+'<div class="sm" style="margin-top:10px">Doses máximas conservadoras; as referências variam. Nunca injetar bupivacaína IV.</div>'}
const COV=[["Hidrocortisona",20],["Prednisolona/prednisona",5],["Metilprednisolona",4],["Triancinolona",4],["Dexametasona",0.75],["Betametasona",0.75]];
function calcCortV(){const i=num(document.getElementById("cvO").value),d=gv("cvD"),o=document.getElementById("cvOut");const eq=d/COV[i][1];
  o.innerHTML='<table class="tbl"><thead><tr><th>Corticoide</th><th>Equivalente</th></tr></thead><tbody>'+COV.map(([n,x],j)=>'<tr'+(j===i?' style="background:var(--accent-soft)"':'')+'><td>'+n+'</td><td class="n">'+fmt(eq*x)+' mg</td></tr>').join("")+'</tbody></table><div class="sm muted" style="margin-top:8px">Equivalência glicocorticoide aproximada (prednisolona 5 mg ≈ dexametasona 0,75 mg). Duração e efeito mineralocorticoide diferem.</div>'}
